messages.content:
Circuit Rush adalah endless runner arcade bertema sirkuit neon di mana pemain mengumpulkan koin data sambil menghindari chip rusak, kapasitor bocor, dan kipas overheat. Saya memakai preset Neon dengan tingkat Menantang dan ukuran rintangan yang disesuaikan agar tetap bisa dilompati pada kecepatan tinggi.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "circuit-rush", title: "Circuit Rush", seed: "circuit-rush-01",
  theme: { preset: "neon" },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 420, maxSpeed: 720, accel: 10 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "chip-rusak",       w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "kapasitor-bocor",  w: 80, h: 24, weight: 2 },
      { type: "hazard", id: "kipas-overheat",   w: 60, h: 70, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 10 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 12, speed: 30 }
  }
});
// END_OF_MANIFEST
```
